  if(t.type==='collabAgentToolCall'){let body=row.lastChild;if(body.tagName==='PRE'){const replacement=element('div','agent-task-list');body.replaceWith(replacement);body=replacement;}body.replaceChildren();for(const [id,agent]of Object.entries(t.agentsStates||{})){const b=element('button','agent-task-row');b.type='button';const status={completed:'已完成',running:'运行中',inProgress:'运行中',pendingInit:'准备中',interrupted:'已停止',errored:'失败',notFound:'不可用'}[agent.status]||agent.status||'任务';b.append(element('span','','协作任务'),element('small','',status));b.onclick=()=>openThread({id,cwd:selected?.cwd,name:'协作任务'}).catch(e=>notify(e.message));body.append(b);}}
