async function loadArchivedRows({more=false}={}){const g=++archivedGeneration,q=$('archived-query').value.trim();if(!more)$('archived-content').replaceChildren(element('div','empty','正在读取归档会话…'));try{const result=await api('/api/archived?limit=30'+(q?'&q='+encodeURIComponent(q):'')+(more&&archivedCursor?'&cursor='+encodeURIComponent(archivedCursor):''));if(g!==archivedGeneration)return;archivedRows=more?[...archivedRows,...result.data]:result.data;archivedCursor=result.nextCursor??null;drawArchivedRows();}catch(error){if(g===archivedGeneration){const retry=element('button','subtle','重试');retry.onclick=()=>loadArchivedRows().catch(e=>notify(e.message));$('archived-content').replaceChildren(element('div','empty',error.message),retry);}throw error;}}
function drawArchivedRows(){const box=$('archived-content');box.replaceChildren();for(const thread of archivedRows){const row=element('div','archived-row'),open=element('button','archived-open'),restore=element('button','subtle','恢复');open.append(element('strong','',thread.name||thread.preview?.slice(0,60)||'未命名会话'),element('p','',[date(thread.updatedAt),shortPath(thread.cwd)].filter(Boolean).join(' · ')),element('small','','查看归档历史 ›'));open.onclick=async()=>{$('archived-dialog').close();project=projectForThread(thread);await openThread({...thread,archived:true},true,{archived:true});};restore.onclick=()=>confirmRestoreThread(thread);row.append(open,restore);box.append(row);}if(!archivedRows.length)box.append(element('div','empty',$('archived-query').value.trim()?'没有匹配名称的归档会话':'暂时没有归档会话'));if(archivedCursor){const more=element('button','subtle archived-more','加载更多归档会话');more.onclick=async()=>{more.disabled=true;try{await loadArchivedRows({more:true});}catch(e){notify(e.message);more.disabled=false;}};box.append(more);}}
function confirmRestoreThread(thread){if(!thread)return;$('action-title').textContent='恢复归档会话';const body=$('action-body'),note=element('p','project-remove-note','恢复“'+(thread.name||'这条会话')+'”到普通会话列表。恢复原会话，不发送新消息；进行中的长期目标仍可能继续。'),status=element('p','archive-status'),actions=element('div','dialog-actions'),cancel=element('button','subtle','取消'),confirm=element('button','primary',restoreRequests.has(thread.id)?'核对恢复结果':'确认恢复');cancel.onclick=()=>$('action-dialog').close();actions.append(cancel,confirm);body.replaceChildren(note,status,actions);const requestId=restoreRequests.get(thread.id)||newUuid();const save=()=>{restoreRequests.set(thread.id,requestId);try{localStorage.setItem('codex-mobile-restore-requests',JSON.stringify(Object.fromEntries(restoreRequests)));}catch{}};confirm.onclick=async()=>{confirm.disabled=true;save();status.textContent='正在恢复并核对实际状态…';try{const result=await api('/api/thread/unarchive',{threadId:thread.id,requestId});if(result.unarchived!==true||result.verified!==true){status.textContent=result.message||'恢复状态尚未核验，请核对后再打开';confirm.textContent='核对恢复结果';confirm.disabled=false;return;}restoreRequests.delete(thread.id);try{localStorage.setItem('codex-mobile-restore-requests',JSON.stringify(Object.fromEntries(restoreRequests)));}catch{}historyCache.delete(thread.id);listCache.clear();const replaceReadonly=archivedView&&selected?.id===thread.id&&!$('archived-dialog').open;$('action-dialog').close();if($('archived-dialog').open)$('archived-dialog').close();project=projectForThread(thread);await openThread({...thread,...result.thread,archived:false},!replaceReadonly,{archived:false});notify('会话已恢复，未发送新消息');}catch(error){status.textContent=isUncertainMutation(error)?'恢复结果尚未确认。再次核对将检查同一请求，不会创建新会话或执行任务。':error.message;confirm.textContent='核对恢复结果';confirm.disabled=false;}};if(!$('action-dialog').open)$('action-dialog').showModal();}
async function showGoalStatus(thread,refresh=false){if(!thread)return;$('action-title').textContent='长期目标状态';const box=$('action-body');box.replaceChildren(element('div','pane-section','正在读取目标状态…'));if(!$('action-dialog').open)$('action-dialog').showModal();try{const result=await api('/api/goal?threadId='+encodeURIComponent(thread.id)+(refresh?'&refresh=1':''));box.replaceChildren();if(!result.goal)box.append(element('div','empty','这条会话未设置长期目标。'));else{const goal=result.goal,status={active:'进行中',paused:'已暂停',blocked:'等待解除阻碍',usageLimited:'用量受限',budgetLimited:'预算受限',complete:'已完成'}[goal.status]||goal.status||'状态未知';box.append(element('p','goal-status-label',status),element('div','goal-objective',goal.objective||''));const metrics=element('dl','goal-metrics');for(const [label,value]of [['已使用 tokens',goal.tokensUsed],['Token 预算',goal.tokenBudget],['已运行时间（秒）',goal.timeUsedSeconds]])if(value!==null&&value!==undefined&&Number.isFinite(Number(value)))metrics.append(element('dt','',label),element('dd','',Number(value).toLocaleString('zh-CN')));for(const [label,value]of [['创建时间',goal.createdAt],['更新时间',goal.updatedAt]])if(value!=null&&messageDate(value))metrics.append(element('dt','',label),element('dd','',messageDate(value)));box.append(metrics);}const button=element('button','subtle','刷新目标状态');button.onclick=()=>showGoalStatus(thread,true);box.append(button);}catch(error){const retry=element('button','subtle','重试');retry.onclick=()=>showGoalStatus(thread,true);box.replaceChildren(element('p','goal-error',error.message),retry);}}

