function validateNewFile(file,excluding=null){const image=/^image\/(png|jpeg|webp|gif)$/.test(file.type)||/\.(png|jpe?g|gif|webp)$/i.test(file.name),limit=(image?8:20)*1024*1024;if(file.size>limit)throw Error(image?'图片不能超过 8 MB':'单个文件不能超过 20 MB');const total=attachments.filter(a=>a!==excluding).reduce((sum,a)=>sum+(Number(a.size)||0),0)+file.size;if(total>60*1024*1024)throw Error('每条消息附件合计不能超过 60 MB');return image;}
async function uploadFiles(files){if(archivedView){notify('请先恢复这条会话，再添加附件');return;}for(const file of files){if(attachments.length>=6){notify('每条消息最多添加 6 个附件');break;}let image;try{image=validateNewFile(file);}catch(error){notify(error.message);continue;}const item={clientId:newUuid(),uploadRequestId:newUuid(),name:file.name,mime:file.type||'application/octet-stream',size:file.size,kind:image?'image':undefined,file,uploading:true,phase:'reading',progress:0,ownerDraftKey:draftKey,...(image?{preview:URL.createObjectURL(file)}:{})};attachments.push(item);renderAttachments();persistDraftNow();await startFileUpload(item);}}
