function currentPaneWorkspace(){return paneWorkspaces.get(activePaneWorkspace)||null;}
function selectedPaneTab(){const state=currentPaneWorkspace();return state?.tabs.find(tab=>tab.id===state.selectedId)||null;}
function paneQuery(){return currentPaneWorkspace()?.query||fileQuery();}
function paneTabKey(tab){return tab.kind==='files'?'files':tab.kind==='file'?'file:'+tab.path:tab.kind==='git'?'git:'+(tab.source||'all')+':'+(tab.path||''):'terminal:'+(tab.terminalTabId||tab.id);}
function restorePaneTabs(){if(paneRestoreLoaded)return;paneRestoreLoaded=true;try{const saved=JSON.parse(localStorage.getItem(PANE_STORAGE)||'null');if(saved?.owner!==token?.slice(-8)||saved.version!==1||!Array.isArray(saved.workspaces))return;for(const input of saved.workspaces.slice(0,20)){if(typeof input.key!=='string'||typeof input.query!=='string')continue;const clean=items=>(Array.isArray(items)?items:[]).filter(tab=>['files','file','git','terminal'].includes(tab.kind)&&typeof tab.id==='string').slice(0,12).map(tab=>({...tab,key:paneTabKey(tab),scrollTop:Number(tab.scrollTop)||0}));paneWorkspaces.set(input.key,{...input,tabs:clean(input.tabs),closed:clean(input.closed),updatedAt:Number(input.updatedAt)||0});}}catch{}}
