function paneTabMetadata(tab){const keys=['id','kind','key','title','path','source','terminalId','terminalTabId','root','inputUncertain','exited','closed','scrollTop','findQuery','findIndex','createdAt'];return Object.fromEntries(keys.filter(key=>tab[key]!==undefined).map(key=>[key,tab[key]]));}
function rememberPaneScroll(){const tab=selectedPaneTab();if(tab&&paneDOMOwner?.workspaceKey===activePaneWorkspace&&paneDOMOwner.tabId===tab.id&&paneDOMOwner.version===paneRenderVersion&&!$('pane-overlay').classList.contains('hidden'))tab.scrollTop=$('pane-content').scrollTop;}
async function selectPaneTab(id){const state=currentPaneWorkspace();if(!state?.tabs.some(tab=>tab.id===id))return;rememberPaneScroll();stopTerminalPoll();state.selectedId=id;state.updatedAt=Date.now();persistPaneTabs();await renderPane();}
