function activatePaneKind(kind){return kind==='git'?openGitTab('all'):kind==='terminal'?createPaneTerminal():ensurePaneTab({kind:'files',path:'',title:'文件'});}
function openFilePaneTab(path){return ensurePaneTab({kind:'file',path,title:path.split('/').pop()||path});}
function openGitTab(source='all',path=''){if(!['all','unstaged','staged','turn'].includes(source))source='all';const names={all:'全部差异',unstaged:'未暂存',staged:'已暂存',turn:'最近一轮'};return ensurePaneTab({kind:'git',source,path,title:path?(path.split('/').pop()+' · '+names[source]):names[source]});}
