function drawPaneTabs(){const state=currentPaneWorkspace(),box=$('pane-tabs');box.replaceChildren();for(const tab of state?.tabs||[]){const wrapper=element('div','pane-tab'+(tab.id===state.selectedId?' selected':'')),button=element('button','pane-tab-select',tab.title||tab.kind),close=element('button','pane-tab-remove','×');button.type='button';button.setAttribute('role','tab');button.setAttribute('aria-selected',String(tab.id===state.selectedId));button.title=tab.kind==='terminal'?'终端 · 关闭标签不会结束进程':tab.path||tab.title;button.onclick=()=>selectPaneTab(tab.id).catch(e=>notify(e.message));close.type='button';close.setAttribute('aria-label','关闭标签 '+(tab.title||tab.kind));close.title='关闭标签'+(tab.kind==='terminal'?'，保留终端进程':'');close.onclick=()=>closePaneTab(tab.id);wrapper.append(button,close);box.append(wrapper);}box.querySelector('.selected')?.scrollIntoView({block:'nearest',inline:'nearest'});}
