function showClosedPaneTabs(){const state=currentPaneWorkspace();if(!state?.closed.length){$('action-title').textContent='最近关闭的标签';$('action-body').replaceChildren(element('div','empty','没有最近关闭的标签。关闭终端标签不会结束其进程。'));$('action-dialog').showModal();return;}showActions('最近关闭的标签',state.closed.map(tab=>({label:(tab.kind==='terminal'?'终端 · ':'')+(tab.title||tab.path||'标签'),run:async()=>{const restored=await ensurePaneTab({...tab});if(restored){state.closed=state.closed.filter(item=>item.id!==tab.id);persistPaneTabs();}}})));}
function showPaneLauncher(){showActions('工作区面板',[{label:'浏览文件',run:()=>activatePaneKind('files')},{label:'查看差异',run:()=>openGitTab('all')},{label:'新建终端',run:()=>createPaneTerminal()},{label:'连接已有终端',run:()=>showExistingTerminals()},{label:'最近关闭的标签',run:showClosedPaneTabs},{label:'查找已打开标签',run:showPaneTabSearch},{separator:true},{label:'关闭其他标签（保留终端进程）',run:()=>closeOtherPaneTabs(false)},{label:'关闭全部标签（保留终端进程）',run:()=>closeOtherPaneTabs(true)}]);}
