function runDiffFind(keep=false){const tab=selectedPaneTab(),pre=$('active-git-diff');if(tab?.kind!=='git')return;clearDiffMarks();const query=$('diff-query').value,needle=query.toLocaleLowerCase(),matches=[];if(pre&&needle){const walker=document.createTreeWalker(pre,NodeFilter.SHOW_TEXT),nodes=[];let node;while(node=walker.nextNode())nodes.push(node);for(const node of nodes){const text=node.nodeValue,lower=text.toLocaleLowerCase();let from=0,index=lower.indexOf(needle),fragment=null;while(index>=0){fragment||=document.createDocumentFragment();fragment.append(document.createTextNode(text.slice(from,index)));const mark=element('mark','diff-search-hit',text.slice(index,index+query.length));mark.dataset.diffHit='true';fragment.append(mark);matches.push(mark);from=index+query.length;index=lower.indexOf(needle,from);}if(fragment){fragment.append(document.createTextNode(text.slice(from)));node.replaceWith(fragment);}}}diffFind={matches,index:matches.length?(keep?Math.max(0,Math.min(tab.findIndex||0,matches.length-1)):0):-1};tab.findQuery=query;tab.findIndex=diffFind.index;persistPaneTabs();updateDiffFindCount();$('diff-find-scope').textContent=tab.diffTruncated?'仅当前已加载差异；完整结果已截断':'仅查找当前已加载差异';if(!keep&&matches.length)jumpDiffFind();}
