function messageMediaText(reason){const messages={INVALID_REFERENCE:'图片引用无效，请重新打开会话。',HISTORY_UNAVAILABLE:'暂时无法读取这条历史消息，请稍后重试。',ITEM_NOT_FOUND:'这条图片消息不存在或已被编辑。',ITEM_MISMATCH:'图片与消息位置不一致，请重新打开会话。',INDEX_OUT_OF_RANGE:'图片位置已失效，请重新打开会话。',UNSUPPORTED_ITEM:'这条消息没有可预览的图片。',FILE_REFERENCE_UNSUPPORTED:'此图片使用原生存储引用，暂时请在电脑端查看。',REMOTE_IMAGE_UNSUPPORTED:'远程图片暂时请在电脑端查看。',MEDIA_NOT_READY:'这张图片尚未生成或已没有可用内容。',INVALID_IMAGE_DATA:'图片数据无效，无法预览。',UNSUPPORTED_IMAGE_FORMAT:'暂时只支持 PNG、JPEG、GIF 和 WebP 图片。',MEDIA_TOO_LARGE:'图片过大，请在电脑端查看。',PATH_NOT_ALLOWED:'这张图片不在已授权的访问范围内。',ACCESS_CHECK_REQUIRED:'图片访问尚不可用，请在电脑端查看。',PERMISSION_REQUIRED:'需要先在 Mac 上允许访问该图片所在目录。',MEDIA_NOT_FOUND:'原图片已不存在，可能已被清理。',UNSAFE_FILE:'图片文件暂时无法安全预览。',MEDIA_CHANGED:'图片已发生变化，请重新打开会话。',AUTH_REQUIRED:'配对已失效，请重新扫描电脑上的二维码。',MEDIA_UNAVAILABLE:'暂时无法读取这张图片，请稍后重试。'};return Object.hasOwn(messages,reason)?messages[reason]:'暂时无法读取这张图片，请在电脑端查看。';}
function nativeMessageImageURL(media,context){if(media?.status!=='candidate')return null;const reference=media?.reference,keys=['threadId','turnId','itemId','index'],validId=value=>typeof value==='string'&&/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$/.test(value)&&!/^(?:data|file|https?):/i.test(value);if(!context||![context.threadId,context.turnId,context.itemId].every(validId)||!reference||Array.isArray(reference)||Object.keys(reference).length!==4||Object.keys(reference).some(key=>!keys.includes(key))||!keys.slice(0,3).every(key=>validId(reference[key])&&reference[key]===context[key])||!Number.isSafeInteger(reference.index)||reference.index<0||reference.index>2048||typeof media.url!=='string'||!media.url.startsWith('/api/thread-media?')||media.url.includes('#'))return null;const query=new URLSearchParams(media.url.slice('/api/thread-media?'.length)),names=[...query.keys()];if(names.length!==4||new Set(names).size!==4||names.some(key=>!keys.includes(key))||keys.some(key=>query.get(key)!==String(reference[key])))return null;return media.url;}
function messageImageURL(media,context){if(media?.status==='unresolved')return null;if(/^\/api\/attachment\?id=[a-f0-9]{48}$/.test(media?.url||''))return media.url;if(/^data:image\/(?:png|jpeg|gif|webp);base64,[A-Za-z0-9+/\r\n]+={0,2}$/.test(media?.url||''))return media.url;return nativeMessageImageURL(media,context);}
async function fetchMessageImageBlob(url,{signal,media,context}={}){if(typeof url!=='string')throw Object.assign(Error(messageMediaText('INVALID_REFERENCE')),{reason:'INVALID_REFERENCE'});if(!/^\/api\/attachment\?id=[a-f0-9]{48}$/.test(url)&&!/^data:image\/(?:png|jpeg|gif|webp);base64,[A-Za-z0-9+/\r\n]+={0,2}$/.test(url)&&nativeMessageImageURL(media,context)!==url)throw Object.assign(Error(messageMediaText('INVALID_REFERENCE')),{reason:'INVALID_REFERENCE'});const response=await fetch(url,{headers:{authorization:'Bearer '+token},cache:'no-store',signal});if(!response.ok){let reason=response.status===401?'AUTH_REQUIRED':'MEDIA_UNAVAILABLE';if((response.headers.get('content-type')||'').includes('application/json')){try{const result=await response.json();if(result.status==='unresolved'&&typeof result.reason==='string')reason=result.reason;}catch{}}throw Object.assign(Error(messageMediaText(reason)),{reason});}if(Number(response.headers.get('content-length'))>20*1024*1024)throw Object.assign(Error(messageMediaText('MEDIA_TOO_LARGE')),{reason:'MEDIA_TOO_LARGE'});const mime=(response.headers.get('content-type')||'').split(';')[0].trim().toLowerCase();if(!['image/png','image/jpeg','image/gif','image/webp'].includes(mime))throw Object.assign(Error(messageMediaText('UNSUPPORTED_IMAGE_FORMAT')),{reason:'UNSUPPORTED_IMAGE_FORMAT'});const blob=await response.blob();if(blob.size>20*1024*1024)throw Object.assign(Error(messageMediaText('MEDIA_TOO_LARGE')),{reason:'MEDIA_TOO_LARGE'});if(!blob.size||!['image/png','image/jpeg','image/gif','image/webp'].includes(blob.type.toLowerCase()))throw Object.assign(Error(messageMediaText('INVALID_IMAGE_DATA')),{reason:'INVALID_IMAGE_DATA'});return blob;}
function keepMessageMediaPosition(context,mutate){if(!context.threadId||selected?.id!==context.threadId)return false;const box=$('messages'),follow=pinned&&!conversationFind.open,position=follow?null:anchor(),top=box.scrollTop;mutate();if(follow)latest();else if(position)restoreAnchor(position);else box.scrollTop=top;return true;}
function disposeMessageMedia(state){if(state.disposed)return;state.disposed=true;state.controller?.abort();clearTimeout(state.timer);if(state.url)URL.revokeObjectURL(state.url);state.url=null;state.blob=null;messageMediaStates.delete(state);}
function releaseMessageMedia(root=null){for(const state of messageMediaStates)if(!root||root.contains(state.host))disposeMessageMedia(state);}
async function decodeMessageImage(url,signal){const image=element('img','message-image');image.alt='消息中的图片';image.decoding='async';return new Promise((resolve,reject)=>{let settled=false;const finish=error=>{if(settled)return;settled=true;signal.removeEventListener('abort',abort);image.onload=image.onerror=null;if(error){image.removeAttribute('src');reject(Error('图片暂不可用'));}else resolve(image);},abort=()=>finish(true);signal.addEventListener('abort',abort,{once:true});if(signal.aborted){abort();return;}image.onload=()=>finish(false);image.onerror=()=>finish(true);image.src=url;if(image.decode)image.decode().then(()=>finish(false),()=>finish(true));});}
function messageImageCard(media,context,{generating=false,failed=false,generated=false,unavailable=false}={}){const host=element('div','message-media'),placeholder=element('div','message-media-placeholder'),status=element('span','',''),retry=element('button','subtle','重试'),state={host,context,disposed:false,url:null,blob:null,controller:null,timer:null};retry.type='button';placeholder.append(element('span','message-media-symbol','▧'),status,retry);host.append(placeholder);messageMediaStates.add(state);const source=messageImageURL(media,context);if(generating){status.textContent='图片生成中…';retry.hidden=true;return host;}if(failed){status.textContent='图片生成未完成，请查看任务回复。';retry.hidden=true;return host;}if(unavailable){status.textContent='暂时无法确认图片状态，请稍后重新打开会话。';retry.hidden=true;return host;}if(!source){status.textContent=messageMediaText(media?.reason||(media?.reference?'INVALID_REFERENCE':'MEDIA_UNAVAILABLE'));retry.hidden=true;return host;}
 const load=async()=>{if(state.disposed||!host.isConnected)return;state.controller?.abort();state.controller=new AbortController();status.textContent='正在加载图片…';retry.disabled=true;retry.hidden=true;clearTimeout(state.timer);state.timer=setTimeout(()=>state.controller?.abort(),45000);let objectURL=null;try{const blob=await fetchMessageImageBlob(source,{signal:state.controller.signal,media,context});if(state.disposed)return;objectURL=URL.createObjectURL(blob);const image=await decodeMessageImage(objectURL,state.controller.signal);if(state.disposed||!host.isConnected||selected?.id!==context.threadId){URL.revokeObjectURL(objectURL);return;}const open=element('button','message-media-open'),actions=element('div','message-media-actions'),view=element('button','','查看大图'),download=element('button','','下载原图');open.type=view.type=download.type='button';open.setAttribute('aria-label',generated?'查看生成的图片':'查看图片');open.append(image);view.onclick=open.onclick=()=>openMessageImageViewer(blob);download.onclick=()=>downloadMessageImage(blob);actions.append(view,download);state.blob=blob;state.url=objectURL;objectURL=null;keepMessageMediaPosition(context,()=>host.replaceChildren(open,actions));}catch(error){if(objectURL)URL.revokeObjectURL(objectURL);if(state.disposed||!host.isConnected)return;keepMessageMediaPosition(context,()=>{status.textContent=messageMediaText(error.reason||'MEDIA_UNAVAILABLE');retry.disabled=false;retry.hidden=false;});}finally{clearTimeout(state.timer);}};retry.onclick=load;Promise.resolve().then(load);return host;}
function renderUserMessageMedia(record,item,context){const signature=JSON.stringify([context.threadId,item.content]);if(record.mediaSignature===signature)return;record.mediaSignature=signature;releaseMessageMedia(record.content);const hasMedia=(item.content||[]).some(content=>content.type==='attachment'||isMessageImage(content));if(!hasMedia){record.content.textContent=record.text;return;}record.content.textContent=(item.content||[]).filter(content=>content.type==='text').map(content=>content.text||'').join('\n');for(const media of item.content||[])if(isMessageImage(media))record.content.append(messageImageCard(media,context));else if(media.type==='attachment')record.content.append(historyAttachmentCard(media));}
function renderGeneratedImage(item,turnId){const key=turnId+':'+item.id,context={threadId:selected?.id,turnId,itemId:item.id},turn=ensureTurn(turnId);let record=records.get(key);if(!record){const node=element('article','message agent generated-image'),content=element('div','message-content');node.dataset.item=key;node.append(content);turn.append(node);record={node,content,user:false,text:'生成的图片'};records.set(key,record);}const signature=JSON.stringify([context.threadId,item.status,item.media]);if(record.mediaSignature===signature)return;record.mediaSignature=signature;releaseMessageMedia(record.content);record.content.replaceChildren(messageImageCard(item.media,context,{generating:['inProgress','in_progress','generating'].includes(item.status),failed:item.status==='failed',unavailable:!['completed','failed','inProgress','in_progress','generating'].includes(item.status),generated:true}));}
function clearMessageImageViewer(){$('message-image-full').removeAttribute('src');if(imageViewerURL)URL.revokeObjectURL(imageViewerURL);imageViewerURL=null;imageViewerBlob=null;}
function closeMessageImageViewer(){if($('message-image-dialog').open)$('message-image-dialog').close();clearMessageImageViewer();}
function openMessageImageViewer(blob){clearMessageImageViewer();imageViewerBlob=blob;imageViewerURL=URL.createObjectURL(blob);$('message-image-full').src=imageViewerURL;if(!$('message-image-dialog').open)$('message-image-dialog').showModal();}
function downloadMessageImage(blob){const extension={'image/png':'png','image/jpeg':'jpg','image/gif':'gif','image/webp':'webp'}[blob.type]||'png',url=URL.createObjectURL(blob),link=element('a');link.href=url;link.download='Codex-图片.'+extension;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}

function isMessageImage(value){return ['image','localImage','local_image'].includes(value?.type)||value?.type==='attachment'&&isImageAttachment(value);}
